var tile = (page, name) => page.locator("ue-asset-tile .AssetTile", { has: page.locator(".AssetTile__name", { hasText: exactly(name) }) });
var tileSelection = (page) => texts(page, "ue-asset-tile .AssetTile.is-selected .AssetTile__name");
var cardOf = (target) => target.locator(".AssetTile__card");
scenario("AssetTile: hover looks of folder and asset tiles", "AssetTile", async (page) => {
  const folder = tile(page, "Audio");
  assert2.equal(await fill(cardOf(folder)), "rgba(0, 0, 0, 0)", "a folder has no card fill at rest");
  await folder.hover();
  assert2.equal(await fill(cardOf(folder)), await token(page, "secondary"));
  assert2.match(await prop(cardOf(folder), "box-shadow"), /rgba\(0, 0, 0, 0\.5\)/);
  assert2.equal(await prop(folder.locator(".AssetTile__name"), "color"), await token(page, "white"));
  assert2.equal(await pseudoShadow(cardOf(folder)), "none", "a hovered folder gets no outline");
  const asset = tile(page, "SM_Chair");
  await asset.hover();
  assert2.equal(await fill(asset.locator(".AssetTile__nameArea")), await token(page, "hover"));
  assert2.ok((await pseudoShadow(cardOf(asset))).includes(await token(page, "hover")), "assets get the hover outline");
});
scenario("AssetTile: click selects one tile, Ctrl/Cmd toggles and Shift selects a range", "AssetTile", async (page) => {
  await tile(page, "Architecture").click();
  assert2.deepEqual(await tileSelection(page), ["Architecture"]);
  await tile(page, "Audio").click();
  assert2.deepEqual(await tileSelection(page), ["Audio"], "a plain click replaces the selection");
  assert2.equal(await attr(tile(page, "Audio"), "aria-selected"), "true");
  assert2.equal(await attr(tile(page, "Architecture"), "aria-selected"), "false");
  await tile(page, "Materials").click({ modifiers: ["Control"] });
  assert2.deepEqual(await tileSelection(page), ["Audio", "Materials"]);
  assert2.equal(await page.locator("ue-asset-tile .AssetTilePreview__status").textContent(), "2 selected: Audio, Materials");
  await tile(page, "Audio").click({ modifiers: ["Control"] });
  assert2.deepEqual(await tileSelection(page), ["Materials"], "Ctrl+click on a selected tile removes it");
  await tile(page, "Architecture").click();
  await tile(page, "Materials").click({ modifiers: ["Shift"] });
  assert2.deepEqual(await tileSelection(page), ["Architecture", "Audio", "Blueprints", "Materials"]);
});
