  assert2.equal(await fill(cbRow(page, "Architecture")), await token(page, "select-parent"));
  await cbRow(page, "Architecture").locator(".ContentBrowser__exp").click();
  assert2.deepEqual(await cbSelectedRow(page), ["Architecture"], "collapsing an ancestor of the selection selects it");
